using System;
using System.Globalization;
using System.Threading.Tasks;

internal static class Program
{
    private sealed class Node
    {
        private readonly Node left;
        private readonly Node right;

        private Node(Node left, Node right)
        {
            this.left = left;
            this.right = right;
        }

        public static Node Build(int depth)
        {
            if (depth == 0)
                return new Node(null, null);

            return new Node(Build(depth - 1), Build(depth - 1));
        }

        public long Check()
        {
            if (left == null)
                return 1;

            return 1 + left.Check() + right.Check();
        }
    }

    private static long StretchCheck(int depth)
    {
        return Node.Build(depth).Check();
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        long stretchCheck = StretchCheck(n + 1);
        Console.WriteLine(
            "stretch tree of depth {0}\t check: {1}",
            n + 1, stretchCheck);

        Node longLivedTree = Node.Build(n);

        int groupCount = n >= 4 ? (n - 4) / 2 + 1 : 0;
        string[] results = new string[groupCount];

        Parallel.For(0, groupCount, index =>
        {
            int depth = 4 + index * 2;
            long iterations = 1L << (n - depth + 4);
            long checksum = 0;

            for (long i = 0; i < iterations; ++i)
                checksum += Node.Build(depth).Check();

            results[index] = string.Format(
                CultureInfo.InvariantCulture,
                "{0}\t trees of depth {1}\t check: {2}",
                iterations, depth, checksum);
        });

        foreach (string result in results)
            Console.WriteLine(result);

        Console.WriteLine(
            "long lived tree of depth {0}\t check: {1}",
            n, longLivedTree.Check());

        GC.KeepAlive(longLivedTree);
    }
}
