using System;
using System.Globalization;
using System.Numerics;
using System.Text;

internal static class Program
{
    private static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        BigInteger numerator = BigInteger.One;
        BigInteger denominator = BigInteger.One;
        BigInteger accumulator = BigInteger.Zero;

        int k = 0;
        int produced = 0;
        var output = new StringBuilder();

        while (produced < n)
        {
            ++k;
            int factor = 2 * k + 1;

            accumulator = (accumulator + (numerator << 1)) * factor;
            numerator *= k;
            denominator *= factor;

            if (numerator > accumulator)
                continue;

            BigInteger digit = BigInteger.DivRem(
                numerator * 3 + accumulator,
                denominator,
                out BigInteger remainder);

            if (remainder + numerator >= denominator)
                continue;

            output.Append((char)('0' + (int)digit));
            ++produced;

            if (produced % 10 == 0 || produced == n)
            {
                int partial = produced % 10;
                if (partial != 0)
                    output.Append(' ', 10 - partial);

                output.Append('\t');
                output.Append(':');
                output.Append(produced.ToString(CultureInfo.InvariantCulture));
                output.Append('\n');
            }

            accumulator = (accumulator - denominator * digit) * 10;
            numerator *= 10;
        }

        Console.Write(output.ToString());
    }
}
