internal static class Program
{
    private static readonly string[] Fragments =
    {
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT"
    };

    private static ulong Encode(string text)
    {
        ulong value = 0;
        foreach (char c in text)
        {
            value = (value << 2) |
                    (ulong)(c == 'A' ? 0 : c == 'C' ? 1 : c == 'G' ? 2 : 3);
        }
        return value;
    }

    private static void AppendFrequencies(
        StringBuilder output, long[] counts, int k)
    {
        int[] order = new int[counts.Length];
        long total = 0;

        for (int i = 0; i < counts.Length; i++)
        {
            order[i] = i;
            total += counts[i];
        }

        Array.Sort(order, (a, b) =>
        {
            int comparison = counts[b].CompareTo(counts[a]);
            return comparison != 0 ? comparison : a.CompareTo(b);
        });

        const string alphabet = "ACGT";

        foreach (int index in order)
        {
            if (counts[index] == 0)
                continue;

            if (k == 2)
                output.Append(alphabet[index >> 2]);

            output.Append(alphabet[index & 3]);
            output.Append(' ');
            output.Append(
                (100.0 * counts[index] / total)
                .ToString("F3", CultureInfo.InvariantCulture));
            output.Append('\n');
        }

        output.Append('\n');
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);
        _ = n;

        byte[] codes = new byte[256];
        for (int i = 0; i < codes.Length; i++)
            codes[i] = 255;

        codes['A'] = codes['a'] = 0;
        codes['C'] = codes['c'] = 1;
        codes['G'] = codes['g'] = 2;
        codes['T'] = codes['t'] = 3;

        long[] singles = new long[4];
        long[] pairs = new long[16];
        long[] occurrences = new long[Fragments.Length];

        ulong target3 = Encode(Fragments[0]);
        ulong target4 = Encode(Fragments[1]);
        ulong target6 = Encode(Fragments[2]);
        ulong target12 = Encode(Fragments[3]);
        ulong target18 = Encode(Fragments[4]);

        const ulong mask6 = (1UL << 12) - 1;
        const ulong mask12 = (1UL << 24) - 1;
        const ulong mask18 = (1UL << 36) - 1;

        ulong rolling = 0;
        int available = 0;

        bool active = false;
        bool finished = false;
        bool lineStart = true;
        int mode = 0; // 0: sequence, 1: header, 2: comment
        int headerPosition = 0;
        bool headerMatches = true;
        const string wantedHeader = "THREE";

        byte[] buffer = new byte[1 << 20];

        using (Stream input = Console.OpenStandardInput())
        {
            int bytesRead;
            while (!finished &&
                   (bytesRead = input.Read(buffer, 0, buffer.Length)) != 0)
            {
                for (int i = 0; i < bytesRead; i++)
                {
                    byte b = buffer[i];

                    if (b == '\r' || b == '\n')
                    {
                        if (mode == 1)
                            active = headerMatches && headerPosition >= 5;

                        mode = 0;
                        lineStart = true;
                        continue;
                    }

                    if (mode == 1)
